// CAPTURA Y PROCESAMIENTO DE ACCIONES DE USUARIO
const actionData = $json;

// Extraer información de la acción
const action = {
  type: actionData.action || actionData.type || 'unknown',
  element: actionData.element || '',
  value: actionData.value || '',
  timestamp: actionData.timestamp || new Date().toISOString(),
  sessionId: actionData.sessionId || `session_${Date.now()}`,
  url: actionData.url || '',
  title: actionData.title || '',
  selector: actionData.selector || '',
  coordinates: actionData.coordinates || null
};

// Crear respuesta detallada con información de los pasos capturados
const response = {
  success: true,
  message: `✅ Acción capturada exitosamente: ${action.type}`,
  capturedAction: {
    step: action.type,
    target: action.element,
    value: action.value,
    page: action.title,
    url: action.url,
    timestamp: action.timestamp,
    sessionId: action.sessionId
  },
  metadata: {
    processingTime: new Date().toISOString(),
    actionCount: 1, // Se incrementará en implementaciones futuras
    status: 'captured_and_stored'
  },
  nextSteps: {
    continue: 'Continúe realizando acciones en la página',
    generate: 'Use el botón Generate with AI cuando termine'
  }
};

// Log detallado para monitoreo
console.log('🎯 ACCIÓN CAPTURADA:', {
  tipo: action.type,
  elemento: action.element,
  valor: action.value,
  página: action.title,
  sesión: action.sessionId
});

return [{json: response}];
